import React, { useState, useEffect, useRef, useCallback } from "react";
import "./DisplayPanel.css";
import { io } from "socket.io-client";

// Helper function to get the server URL dynamically
const getServerUrl = () => {
  return `http://${window.location.hostname}:4000`;
};

// Helper function to generate a client ID
function generateClientId() {
  const newClientId = 'display_' + Math.random().toString(36).substring(2, 15);
  localStorage.setItem('displayPanelClientId', newClientId);
  return newClientId;
}

const DisplayPanel = () => {
  const [socket, setSocket] = useState(null);
  const [targets, setTargets] = useState([]);
  const [availableFeeds, setAvailableFeeds] = useState({});
  const [selectedImages, setSelectedImages] = useState([]);
  const [activeTarget, setActiveTarget] = useState(null);
  const [connected, setConnected] = useState(false);
  const [imageRefreshTimestamps, setImageRefreshTimestamps] = useState({});
  const [imageErrors, setImageErrors] = useState({});
  const [fullScreenImageIndex, setFullScreenImageIndex] = useState(null);
  const [isTargetContainerCollapsed, setIsTargetContainerCollapsed] = useState(true);
  // Using the useState initializer function to avoid unnecessary re-renders
  const [clientId] = useState(() => localStorage.getItem('displayPanelClientId') || generateClientId());
  // Add state to track if we're in mobile view
  const [isMobileView, setIsMobileView] = useState(window.innerWidth <= 768);

  // Reference for the display content div
  const displayContentRef = useRef(null);

  // Server configuration - using dynamic URL
  const SERVER_URL = getServerUrl();

  // Function to refresh the display panel state - wrapped in useCallback to prevent dependency issues
  const refreshDisplayPanel = useCallback(async () => {
    if (!connected || !socket) return;

    try {
      console.log(`Refreshing display panel for client ${clientId}`);
      await fetch(`${SERVER_URL}/display_panel_page_refresh`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ client_id: clientId }),
      });
      console.log("Display panel refresh request sent");
    } catch (error) {
      console.error("Error refreshing display panel:", error);
    }
  }, [connected, socket, clientId, SERVER_URL]);

  // Initialize socket connection
  useEffect(() => {
    const newSocket = io(SERVER_URL);

    newSocket.on('connect', () => {
      console.log('Connected to server');
      setConnected(true);

      // Clear any error states on reconnect
      setImageErrors({});
    });

    newSocket.on('disconnect', () => {
      console.log('Disconnected from server');
      setConnected(false);
    });

    setSocket(newSocket);

    // Clean up socket connection on component unmount
    return () => newSocket.disconnect();
  }, [SERVER_URL]);

  // Add resize listener to detect mobile view
  useEffect(() => {
    const handleResize = () => {
      setIsMobileView(window.innerWidth <= 768);
    };

    // Set initial state
    handleResize();

    // Add event listener
    window.addEventListener('resize', handleResize);

    // Clean up
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  // Handle page refresh
  useEffect(() => {
    // Define a handler that calls refreshDisplayPanel
    const onPageShow = () => {
      console.log("Page show event detected");
      if (connected && socket) {
        refreshDisplayPanel();
      } else {
        console.log("Not connected yet, cannot refresh");
        // Try again in a second if we're not connected
        setTimeout(() => {
          if (connected && socket) {
            refreshDisplayPanel();
          }
        }, 1000);
      }
    };

    // Listen for the 'pageshow' event (fires on load/reload)
    window.addEventListener("pageshow", onPageShow);
    // Listen for 'popstate' to capture back/forward navigation
    window.addEventListener("popstate", onPageShow);

    return () => {
      window.removeEventListener("pageshow", onPageShow);
      window.removeEventListener("popstate", onPageShow);
    };
  }, [connected, socket, refreshDisplayPanel]);

  // Setup event listeners when socket is connected
  useEffect(() => {
    if (!socket || !connected) return;

    console.log("Setting up socket event listeners");

    // Request the list of available targets and feeds
    socket.emit('display_get_feeds');
    console.log("Requested feeds");

    // Listen for available targets
    socket.on('display_available_targets', (data) => {
      console.log('Received targets:', data);
      setTargets(data);
    });

    // Listen for available feeds
    socket.on('display_available_feeds', (data) => {
      console.log('Received feeds:', data);
      setAvailableFeeds(data);
    });

    // Listen for image updates
    socket.on('image_updated', (data) => {
      console.log(`Image updated event received for: ${data.target}/${data.name}`);
      refreshImageSrc(data.target, data.name);
    });

    // Run refresh once connected
    refreshDisplayPanel();

    // Set up polling for available feeds
    const intervalId = setInterval(() => {
      socket.emit('display_get_feeds');
      console.log("Polling for feeds");
    }, 5000); // Poll every 5 seconds

    // Cleanup function
    return () => {
      socket.off('display_available_targets');
      socket.off('display_available_feeds');
      socket.off('image_updated');
      clearInterval(intervalId);
    };
  }, [socket, connected, refreshDisplayPanel]);

  // Handle saved subscriptions from server
  useEffect(() => {
    if (!socket || !connected) return;

    socket.on('display_saved_subscriptions', (subscriptions) => {
      console.log('Received saved subscriptions:', subscriptions);

      if (!subscriptions || subscriptions.length === 0) {
        console.log('No saved subscriptions found');
        return;
      }

      // Process each saved subscription
      setSelectedImages(prevSelectedImages => {
        const newSelectedImages = [...prevSelectedImages];

        subscriptions.forEach(subscription => {
          const { target, name } = subscription;

          // Check if already in array
          const existingIndex = newSelectedImages.findIndex(img => 
            img.targetId === target && img.imageName === name
          );

          if (existingIndex === -1) {
            console.log(`Restoring saved image: ${target}/${name}`);
            newSelectedImages.push({ targetId: target, imageName: name });

            // Reset the refresh timestamp to trigger a new image load
            refreshImageSrc(target, name);
          }
        });

        return newSelectedImages;
      });

      // If we have images and no fullscreen image is set, set the first one as fullscreen
      setFullScreenImageIndex(prevIndex => {
        if (prevIndex === null && (selectedImages.length > 0 || subscriptions.length > 0)) {
          return 0;
        }
        return prevIndex;
      });

      // Set active target if we have subscriptions and no active target
      if (subscriptions.length > 0 && !activeTarget) {
        setActiveTarget(subscriptions[0].target);
      }
    });

    return () => {
      socket.off('display_saved_subscriptions');
    };
  }, [socket, connected, selectedImages, fullScreenImageIndex, activeTarget]);

  // Function to refresh an image's timestamp
  const refreshImageSrc = (targetId, imageName) => {
    console.log(`Refreshing image timestamp for ${targetId}/${imageName}`);
    setImageRefreshTimestamps(prev => ({
      ...prev,
      [`${targetId}-${imageName}`]: Date.now()
    }));

    // Reset any error state
    setImageErrors(prev => ({
      ...prev,
      [`${targetId}-${imageName}`]: false
    }));
  };

  // Handle image selection
  const handleImageSelect = (targetId, imageName) => {
    // Check if already selected
    const existingIndex = selectedImages.findIndex(img => 
      img.targetId === targetId && img.imageName === imageName
    );

    if (existingIndex !== -1) {
      // Remove from selection
      const updatedImages = [...selectedImages];
      updatedImages.splice(existingIndex, 1);
      setSelectedImages(updatedImages);

      // If the fullscreen image is being removed, reset fullscreen state
      if (fullScreenImageIndex === existingIndex) {
        setFullScreenImageIndex(null);
      } else if (fullScreenImageIndex !== null && fullScreenImageIndex > existingIndex) {
        // Adjust fullscreen index if an image before it was removed
        setFullScreenImageIndex(fullScreenImageIndex - 1);
      }

      // Clear any error state for this image
      setImageErrors(prev => {
        const newErrors = {...prev};
        delete newErrors[`${targetId}-${imageName}`];
        return newErrors;
      });

      // Unsubscribe from the feed
      if (socket && connected) {
        socket.emit('display_unsubscribe_from_image', { 
          target: targetId, 
          name: imageName,
          client_id: clientId 
        });
        console.log(`Unsubscribed from ${targetId}/${imageName}`);
      }
    } else if (imageName) {
      // Add to selection immediately so the UI shows it
      console.log(`Adding ${targetId}/${imageName} to selected images`);

      // If this is the first image, make it fullscreen automatically
      const newImages = [...selectedImages, { targetId, imageName }];
      setSelectedImages(newImages);

      // If there was previously no image (this is the first one), set it to fullscreen
      if (selectedImages.length === 0) {
        setFullScreenImageIndex(0);
      }

      setActiveTarget(targetId);

      // Subscribe to the feed
      if (socket && connected) {
        console.log(`Subscribing to ${targetId}/${imageName}`);
        socket.emit('display_subscribe_to_image', { 
          target: targetId, 
          name: imageName,
          client_id: clientId 
        });

        // Reset the refresh timestamp to trigger a new image load
        refreshImageSrc(targetId, imageName);
      }
    }
  };

  // Handle target selection
  const handleTargetClick = (targetId) => {
    setActiveTarget(targetId);
  };

  // Handle toggling fullscreen mode for an image
  const handleToggleFullscreen = (index, e) => {
    e.stopPropagation(); // Prevent bubbling to parent elements

    // If current image is already fullscreen, exit fullscreen
    if (fullScreenImageIndex === index) {
      setFullScreenImageIndex(null);
    } else {
      // Otherwise, make this image fullscreen
      setFullScreenImageIndex(index);
    }
  };

  // Handle image load error
  const handleImageError = (selection) => {
    console.error(`Failed to load image: ${selection.targetId}/${selection.imageName}`);

    // Mark this image as having an error
    setImageErrors(prev => ({
      ...prev,
      [`${selection.targetId}-${selection.imageName}`]: true
    }));
  };

  // Toggle target container collapse state
  const toggleTargetContainer = () => {
    setIsTargetContainerCollapsed(!isTargetContainerCollapsed);
  };

  return (
    <div className="display-sub-panel">
      <div 
        ref={displayContentRef}
        className={`display-content ${!isTargetContainerCollapsed ? 'mobile-targets-expanded' : ''}`}
      >
        {/* Image display container */}
        <div className="display-image-container">
          {/* Always show expand button regardless of container state */}
          <button 
            className={`mobile-expand-btn ${isMobileView ? 'mobile' : ''}`}
            onClick={toggleTargetContainer}
            style={{ display: isTargetContainerCollapsed ? 'flex' : 'none' }}
            title="Show Targets"
          >
            ≡
          </button>

          {selectedImages.length > 0 ? (
            selectedImages.map((selection, index) => {
              // Generate a unique cache-busting key
              const cacheKey = imageRefreshTimestamps[`${selection.targetId}-${selection.imageName}`] || Date.now();
              const imageSrc = `${SERVER_URL}/api/images/${selection.targetId}/${selection.imageName}?t=${cacheKey}`;
              const hasError = imageErrors[`${selection.targetId}-${selection.imageName}`];
              const isFullscreen = fullScreenImageIndex === index;

              // Only render the image if it's fullscreen or no image is in fullscreen mode
              if (fullScreenImageIndex === null || isFullscreen) {
                return (
                  <div key={`${selection.targetId}-${selection.imageName}-${index}`} 
                       className={`display-image ${hasError ? 'image-error' : ''} ${isFullscreen ? 'fullscreen' : ''}`}>

                    {!hasError ? (
                      <img 
                        src={imageSrc}
                        alt={`${selection.targetId} - ${selection.imageName}`}
                        onLoad={() => {
                          // Reset error state if it was previously in error
                          if (hasError) {
                            setImageErrors(prev => ({
                              ...prev,
                              [`${selection.targetId}-${selection.imageName}`]: false
                            }));
                          }
                        }}
                        onError={() => handleImageError(selection)}
                      />
                    ) : (
                      <div className="subscription-message">
                        Subscribed to {selection.targetId}/{selection.imageName}
                      </div>
                    )}

                    <div className="image-overlay">
                      <span>{selection.targetId}: {selection.imageName}</span>
                      <div className="image-controls">
                        <button 
                          onClick={(e) => handleToggleFullscreen(index, e)}
                          className="toggle-size-btn"
                          title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
                        >
                          {isFullscreen ? "⊖" : "⊕"}
                        </button>
                        <button 
                          onClick={() => handleImageSelect(selection.targetId, selection.imageName)}
                          className="remove-btn"
                          title="Remove"
                        >
                          &times;
                        </button>
                      </div>
                    </div>
                  </div>
                );
              } else {
                // Return null for images that should be hidden when in fullscreen mode
                return null;
              }
            })
          ) : (
            <div className="no-images-placeholder">
              Select images from the target panels
            </div>
          )}
        </div>

        {/* Target container - always rendered but conditionally shown */}
        <div 
          className="display-target-container" 
          style={{ visibility: isTargetContainerCollapsed ? 'hidden' : 'visible', opacity: isTargetContainerCollapsed ? 0 : 1 }}
        >
          <button 
            className="mobile-collapse-btn"
            onClick={toggleTargetContainer}
            style={{ display: isTargetContainerCollapsed ? 'none' : 'flex' }}
            title="Show Images"
          >
            ×
          </button>

            {targets.length > 0 ? (
              targets.map(target => (
                <div 
                  key={target.id} 
                  className={`display-panel-target ${activeTarget === target.id ? 'active-target' : ''}`}
                  onClick={() => handleTargetClick(target.id)}
                >
                  <h3>{target.name || target.id}</h3>
                  <select 
                    className="display-image-name"
                    onChange={(e) => handleImageSelect(target.id, e.target.value)}
                    value=""
                    onClick={(e) => e.stopPropagation()}
                  >
                    <option value="">Select an image</option>
                    {availableFeeds[target.id]?.map(name => (
                      <option key={name} value={name}>{name}</option>
                    ))}
                  </select>
                  <div className="selected-target-images">
                    {selectedImages
                      .filter(img => img.targetId === target.id)
                      .map((img, idx) => {
                        const hasError = imageErrors[`${img.targetId}-${img.imageName}`];
                        return (
                          <div key={idx} className="selected-image-badge">
                            {img.imageName}
                            <button 
                              onClick={(e) => {
                                e.stopPropagation();
                                handleImageSelect(target.id, img.imageName);
                              }}
                              className="remove-badge"
                            >
                              &times;
                            </button>
                          </div>
                        );
                      })}
                  </div>
                </div>
              ))
            ) : (
              <div className="no-targets-placeholder">
                No targets available
              </div>
            )}
          </div>
        </div>
      </div>
  );
};

export default DisplayPanel;
